// Tissot's Indicatrix — Geo, route: jsx
// Source: tissots-indicatrix
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString, MultiPolygon } from 'geojson';
import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

const MARGIN = { top: 10, right: 10, bottom: 10, left: 10 };

// Mercator diverges at the poles, so the frame and the lattice both stop short of them.
const LAT_LIMIT = 80;
const STEP = 10;

const graticule = d3.geoGraticule10();

// Equal-radius small circles on a lat/lon lattice. Every one is 2.5 degrees across on the
// globe, so whatever the projection does to their size and shape is its distortion.
const indicatrices: MultiPolygon = {
  type: 'MultiPolygon',
  coordinates: buildLattice()
};

function buildLattice(): MultiPolygon['coordinates'] {
  const circle = d3
    .geoCircle<unknown, [number, number]>()
    .center((d) => d)
    .radius(STEP / 4)
    .precision(12);
  const coordinates: MultiPolygon['coordinates'] = [];
  for (let lat = -LAT_LIMIT + STEP / 2; lat <= LAT_LIMIT - STEP / 2; lat += STEP) {
    for (let lon = -180; lon < 180; lon += STEP) {
      coordinates.push(circle([lon, lat]).coordinates);
    }
  }
  return coordinates;
}

// Mercator's vertical coordinate, in units of the projection's scale.
function mercatorY(latitude: number): number {
  return Math.log(Math.tan(Math.PI / 4 + (latitude * Math.PI) / 360));
}

export default function TissotsIndicatrix({ width }: { width: number }) {
  const innerWidth = Math.max(width - MARGIN.left - MARGIN.right, 0);
  const innerHeight = Math.round((innerWidth / Math.PI) * mercatorY(LAT_LIMIT));
  const height = innerHeight + MARGIN.top + MARGIN.bottom;

  const shapes = useMemo(() => {
    // A whole world of longitude spans the frame, which fixes the scale outright.
    const projection = d3
      .geoMercator()
      .scale(innerWidth / (2 * Math.PI))
      .translate([innerWidth / 2, innerHeight / 2]);
    // 576 circles land ~20k points in one path attribute; one decimal is all the frame resolves.
    const path = d3.geoPath(projection).digits(1);
    return {
      graticule: path(graticule) ?? undefined,
      land: path(worldLand) ?? undefined,
      circles: path(indicatrices) ?? undefined
    };
  }, [innerWidth, innerHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Tissot's indicatrix: a lattice of equal-size geographic circles on a Mercator world map, stretching toward the poles"
    >
      <defs>
        <clipPath id="tissot-frame">
          <rect width={innerWidth} height={innerHeight} />
        </clipPath>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g clipPath="url(#tissot-frame)">
          <path d={shapes.graticule} fill="none" stroke="var(--line)" strokeWidth={0.5} />
          <path
            d={shapes.land}
            fill="var(--muted)"
            fillOpacity={0.3}
            stroke="var(--muted)"
            strokeWidth={0.4}
          />
          <path
            d={shapes.circles}
            fill="var(--accent)"
            fillOpacity={0.18}
            stroke="var(--accent)"
            strokeWidth={0.8}
          />
        </g>
        <rect width={innerWidth} height={innerHeight} fill="none" stroke="var(--line)" />
      </g>
    </svg>
  );
}
